create or replace function public.record_customer_payment(p_customer_id uuid,p_amount numeric,p_payment_date date,p_method text,p_invoice_id uuid default null,p_upi_reference text default null,p_notes text default null) returns jsonb language plpgsql security invoker set search_path = '' as $$ declare v_user uuid:=auth.uid();v_payment_id uuid:=gen_random_uuid();v_due numeric;v_alloc numeric;begin if v_user is null then raise exception 'Authentication required';end if;if p_amount<=0 then raise exception 'Payment amount must be positive';end if;insert into public.customer_payments(id,customer_id,payment_date,amount,payment_method,upi_reference,notes,created_by) values(v_payment_id,p_customer_id,p_payment_date,p_amount,p_method,p_upi_reference,p_notes,v_user);if p_invoice_id is not null then select amount_due into v_due from public.invoices where id=p_invoice_id and billing_customer_id=p_customer_id for update;if not found then raise exception 'Invoice not found for customer';end if;v_alloc:=least(p_amount,v_due);if v_alloc>0 then insert into public.customer_payment_allocations(payment_id,invoice_id,amount) values(v_payment_id,p_invoice_id,v_alloc);update public.invoices set advance_applied=coalesce(advance_applied,0)+v_alloc,amount_due=greatest(0,coalesce(amount_due,0)-v_alloc),status=case when greatest(0,coalesce(amount_due,0)-v_alloc)=0 then 'paid' else 'partially_paid' end,updated_at=now() where id=p_invoice_id;end if;end if;perform public.record_audit_event('customer.payment.recorded','customer_payment',v_payment_id,jsonb_build_object('customer_id',p_customer_id,'invoice_id',p_invoice_id,'amount',p_amount),'application');return jsonb_build_object('payment_id',v_payment_id,'allocated',coalesce(v_alloc,0));end; $$;
revoke all on function public.record_customer_payment(uuid,numeric,date,text,uuid,text,text) from public,anon;grant execute on function public.record_customer_payment(uuid,numeric,date,text,uuid,text,text) to authenticated;
create or replace function public.record_supplier_payment(p_supplier_id uuid,p_amount numeric,p_payment_date date,p_method text,p_purchase_id uuid default null,p_upi_reference text default null,p_notes text default null) returns jsonb language plpgsql security invoker set search_path = '' as $$ declare v_user uuid:=auth.uid();v_payment_id uuid:=gen_random_uuid();v_due numeric;v_alloc numeric;begin if v_user is null then raise exception 'Authentication required';end if;if p_amount<=0 then raise exception 'Payment amount must be positive';end if;insert into public.supplier_payments(id,supplier_id,payment_date,amount,payment_method,upi_reference,notes,created_by) values(v_payment_id,p_supplier_id,p_payment_date,p_amount,p_method,p_upi_reference,p_notes,v_user);if p_purchase_id is not null then select greatest(0,coalesce(sum(coalesce(l.line_total,l.billed_quantity*coalesce(l.unit_rate,0))),0)-coalesce((select sum(spa.amount) from public.supplier_payment_allocations spa where spa.purchase_id=p_purchase_id),0)) into v_due from public.purchase_lines l where l.purchase_id=p_purchase_id;v_alloc:=least(p_amount,v_due);if v_alloc>0 then insert into public.supplier_payment_allocations(payment_id,purchase_id,amount) values(v_payment_id,p_purchase_id,v_alloc);end if;end if;perform public.record_audit_event('supplier.payment.recorded','supplier_payment',v_payment_id,jsonb_build_object('supplier_id',p_supplier_id,'purchase_id',p_purchase_id,'amount',p_amount),'application');return jsonb_build_object('payment_id',v_payment_id,'allocated',coalesce(v_alloc,0));end; $$;
revoke all on function public.record_supplier_payment(uuid,numeric,date,text,uuid,text,text) from public,anon;grant execute on function public.record_supplier_payment(uuid,numeric,date,text,uuid,text,text) to authenticated;
